import React, { useContext } from "react";
import RadioButtonInput from "../../../../inputs/radioButtonInput/RadioButtonInput";
import classificationOptions from "../../../../../data/classificationOptions";
import SectionLayout from "../../../sectionLayout/SectionLayout";
import AppContext from "../../../../context/appContext/AppContext";

function Classification(props) {
    const appCtx = useContext(AppContext);
    const lexicon = appCtx.lexicon.theme.categorization.classification;
    const {classification} = props.inputs;

    const handleOnChangeInputValue = (input) => {
        classification.setValue(input.value);
    }

    return (
        <SectionLayout
            title={lexicon.title}
            description={lexicon.description}
        >
            <RadioButtonInput 
                name={classification.inputName}
                label={lexicon.inputLabel}
                options={classificationOptions[appCtx.currentLanguage]}
                selectedOption={classification.value}
                onChange={handleOnChangeInputValue}
            />
        </SectionLayout>
    );
}

export default Classification;