import React, { useContext } from "react";
import style from "./Solution.module.css";
import inputStyle from "../Inputs.module.css";
import SectionLayout from "../../../sectionLayout/SectionLayout";
import InputField from "../../../../inputs/inputField/InputField";
import BinaryQuestion from "../../../../inputs/binaryQuestion/BinaryQuestion";
import AppContext from "../../../../context/appContext/AppContext";
import { CSSTransition } from "react-transition-group";

function Solution(props) {
    const appCtx = useContext(AppContext);
    const lexicon = appCtx.lexicon.theme.categorization.solution;
    const {inputs} = props;

    const handleOnChangeInputValue = (input) => {
        inputs[input.name].setValue(input.value);
    }

    return (
        <SectionLayout
            className={style.sectionLayout}
            inputsContainerClassName={inputStyle.inputFlexGrow}
            title={lexicon.title}
            description={lexicon.description}
        >
            <InputField 
                className={` ${inputStyle.inputMargin} ${inputStyle.inputFlexGrow}`}
                type="textarea"
                name={inputs.solution.inputName}
                label={lexicon.solution}
                placeholder={lexicon.solutionPlaceholder}
                onChange={handleOnChangeInputValue}
                value={inputs.solution.value}
                error={!inputs.solution.isValid}
                errorMessage={inputs.solution.invalidMessage}
                showErrorMessageWhenEmpty={false}
            />
            <BinaryQuestion
                className={inputStyle.inputMargin}
                name={inputs.usedSql.inputName}
                label={lexicon.usedSql}
                labelPosition="left"
                yesLabel={appCtx.lexicon.yes}
                noLabel={appCtx.lexicon.no}
                value={inputs.usedSql.value}
                onChange={handleOnChangeInputValue}
                language={props.currentLanguage}
            />
            <CSSTransition
                in={inputs.usedSql.value === "yes"}
                timeout={200}
                unmountOnExit
                classNames={{
                    enter: inputStyle.inputEnter,
                    enterActive: inputStyle.inputEnterActive,
                    exit: inputStyle.inputExit,
                    exitActive: inputStyle.inputExitActive,
                }}
            >
                <div className={inputStyle.transitionContainer}>
                    <InputField 
                        className={`${inputStyle.inputMargin} ${inputStyle.inputFlexGrow} ${style.sqlCodeInput}`}
                        type="textarea"
                        name={inputs.sqlCode.inputName}
                        label={lexicon.sqlCode}
                        placeholder="UPDATE table SET field..."
                        onChange={handleOnChangeInputValue}
                        value={inputs.sqlCode.value}
                        error={!inputs.sqlCode.isValid}
                        errorMessage={inputs.sqlCode.invalidMessage}
                        showErrorMessageWhenEmpty={false}
                    />
                </div>
            </CSSTransition>
            {props.classification === 'User Adoption' &&
                <BinaryQuestion
                    className={inputStyle.inputMargin}
                    name={inputs.userGuided.inputName}
                    label={lexicon.userGuided}
                    labelPosition="left"
                    yesLabel={appCtx.lexicon.yes}
                    noLabel={appCtx.lexicon.no}
                    value={inputs.userGuided.value}
                    onChange={handleOnChangeInputValue}
                    language={props.currentLanguage}
                />
            }
        </SectionLayout>
    );
}

export default Solution;