import React, { useCallback, useEffect, useRef} from "react";
import style from "./UnderlineMenu.module.css";

function UnderlineMenu(props) {
    const ul = useRef();
    const items = useRef();
    const underline = useRef();
    const firstRender = useRef(true);

    useEffect(() => {
        items.current = Array.from(ul.current.children);
    }, [props.children]);

    useEffect(() => {
        let selectedItem = null;

        if(!props.selectedItem || props.selected > items.current.length + 1) {
            selectedItem = items.current[0];
        } else {
            selectedItem = items.current[props.selectedItem - 1];
        }

        if(firstRender.current) {
            setTimeout(() => {
                underline.current.style.width = `${selectedItem.getBoundingClientRect().width}px`;
                underline.current.style.left = `${selectedItem.offsetLeft}px`;
            }, 100);
            firstRender.current = false;
        } else {
            underline.current.style.width = `${selectedItem.getBoundingClientRect().width}px`;
            underline.current.style.left = `${selectedItem.offsetLeft}px`;
        }
        
    }, [props.selectedItem]);

    const handleOnClick = useCallback((event) => {
        props.onSelectItem(event.target.closest(`.${style.item}`).getAttribute("item-number"));
    }, []);

    const listItems = props.children.map((item, idx) => {
        const id = `underline-menu-item-${idx + 1}`;
        return (
            <li 
                key={id}
                item-number={idx + 1}
                className={`${style.item} ${(props.selectedItem == idx + 1)? style.selected : ""} ${props.itemClassName? props.itemClassName : ""}`}
            >
                <button onClick={handleOnClick}>{item}</button>
            </li>
    )});

    return (
        <div className={`${style.UnderlineMenu} ${props.className? props.className : ""}`}>
            <ul ref={ul}>
                {listItems}
            </ul>
            <div ref={underline} className={`${style.underline} ${props.underlineClassName? props.underlineClassName : ""}`}></div>
        </div>
    );
}

export default UnderlineMenu;