import React, { useContext, useState } from "react";
import tiersTree from "../../../../../data/tiers/tiersTree";
import classificationData from "../../../../../data/classificationData";
import AppContext from "../../../../context/appContext/AppContext";
import InputField from "../../../../inputs/inputField/InputField";
import InputsTimeline from "../../../inputsTimeline/InputsTimeline";
import SectionLayout from "../../../sectionLayout/SectionLayout";
import style from "./Tiers.module.css";

function Tiers(props) {
    const [currentTier, setCurrentTier] = useState(getCurrentTier(props.inputs));
    const appCtx = useContext(AppContext);
    
    const {inputs, country, maxTier} = props;
    const lexicon = appCtx.lexicon.theme.categorization.tiers;
    
    const handleOnClickStep = (step) => {
        setCurrentTier(step + 1);
    }

    const handleOnChangeInputValue = (input) => {
        const nextTier = (currentTier + 1 > maxTier)? maxTier : currentTier + 1;

        setCurrentTier(nextTier);
        inputs[input.name].setValue(input.value);
        resetNextTiers(nextTier);
    }

    const resetNextTiers = (currentTier) => {
        if(currentTier === maxTier) return;

        for(let tier = currentTier; tier <= maxTier - 1; tier++) {
            inputs[`tier${tier}`].reset();
        }
    }

    const getPath = () => {
        const path = [country.toUpperCase()];

        for(let tier = 1; tier < currentTier; tier++) {
            const tierValue = inputs[`tier${tier}`].value;
            if(!tierValue) break;
            path.push(tierValue);
        }

        return path;
    }

    const options = currentTier === 5
        ? classificationData.find(data => data.classification === props.classification).tier5
        : tiersTree.getDestinations(getPath()).sort();

    return (
        <SectionLayout
            inputsContainerClassName={style.inputsContainer}
            title="Tiers"
            description={lexicon.description}
        >
            <InputsTimeline
                className={style.inputsTimeline}
                steps={createSteps(inputs)}
                currentStep={currentTier - 1}
                onClickStep={handleOnClickStep}
            />
            <InputField
                className={style.select}
                name={inputs[`tier${currentTier}`].inputName}
                type="select"
                selectSize="2"
                options={options}
                value={inputs[`tier${currentTier}`].value}
                onChange={handleOnChangeInputValue}
                disableErrorMessage
            />
        </SectionLayout>
    );
}

function getCurrentTier(inputs) {
    let currentTier = 0;

    for(let tier in inputs) {
        currentTier++;
        if(!inputs[tier].isValid) break;
    }

    return currentTier;
}

function createSteps(inputs) {
    const steps = []
    let currentTier = 1;

    for(let tier in inputs) {

        steps.push({
            name: `Tier ${currentTier++}`,
            value: inputs[tier].value,
            isValid: inputs[tier].isValid
        });
    }

    return steps;
}

export default Tiers;