import React, { useContext } from "react";
import inputStyle from "../Inputs.module.css";
import style from "./Problem.module.css";
import SectionLayout from "../../../sectionLayout/SectionLayout";
import BinaryQuestion from "../../../../inputs/binaryQuestion/BinaryQuestion";
import InputField from "../../../../inputs/inputField/InputField";
import AppContext from "../../../../context/appContext/AppContext";
import { CSSTransition } from "react-transition-group";
import RadioButtonInput from "../../../../inputs/radioButtonInput/RadioButtonInput";
import reopeningReasonOptions from "../../../../../data/reopeningReasonOptions";

function Problem(props) {
    const appCtx = useContext(AppContext);
    const lexicon = appCtx.lexicon.theme.categorization.problem;
    const {inputs} = props;

    const handleOnChangeInputValue = (input) => {
        inputs[input.name].setValue(input.value);
    }

    const reopenReasonOptions = reopeningReasonOptions.map(option => ({
        value: option.value,
        label: lexicon[option.id]
    }));

    return (
        <SectionLayout
            inputsContainerClassName={inputStyle.inputFlexGrow}
            title={lexicon.title}
            description={lexicon.description}
        >
            <InputField 
                className={`${inputStyle.inputMargin} ${inputStyle.inputFlexGrow}`}
                inputClassName={style.problemInput}
                type="textarea"
                name={inputs.problem.inputName}
                label={lexicon.problem}
                placeholder={lexicon.problemPlaceholder}
                onChange={handleOnChangeInputValue}
                value={inputs.problem.value}
                error={!inputs.problem.isValid}
                errorMessage={inputs.problem.invalidMessage}
                showErrorMessageWhenEmpty={false}
            />
            <BinaryQuestion
                className={inputStyle.inputMargin}
                name={inputs.diagnosisMatchProblem.inputName}
                label={lexicon.diagnosisMatchProblem}
                optionsDirection="row"
                // labelPosition="left"
                yesLabel={appCtx.lexicon.yes}
                noLabel={appCtx.lexicon.no}
                value={inputs.diagnosisMatchProblem.value}
                onChange={handleOnChangeInputValue}
                language={props.currentLanguage}
            />
            <BinaryQuestion
                className={inputStyle.inputMargin}
                name={inputs.isReopening.inputName}
                label={lexicon.isReopening}
                // labelPosition="left"
                optionsDirection="row"
                yesLabel={appCtx.lexicon.yes}
                noLabel={appCtx.lexicon.no}
                value={inputs.isReopening.value}
                onChange={handleOnChangeInputValue}
                language={props.currentLanguage}
            />
            <CSSTransition
                in={inputs.isReopening.value === "yes"}
                timeout={40000}
                unmountOnExit
                classNames={{
                    enter: style.reopeningReasonInputEnter,
                    enterActive: style.reopeningReasonInputEnterActive,
                    exit: style.reopeningReasonInputExit,
                    exitActive: style.reopeningReasonInputExitActive,
                }}
            >
                <div className={inputStyle.transitionContainer}>
                    {/* <InputField 
                        className={inputStyle.inputMargin}
                        type="textarea"
                        name={inputs.reopeningReason.inputName}
                        label={lexicon.reopeningReason}
                        placeholder={lexicon.reopeningReasonPlaceholder}
                        onChange={handleOnChangeInputValue}
                        // debouncing
                        value={inputs.reopeningReason.value}
                        error={!inputs.reopeningReason.isValid}
                        errorMessage={inputs.reopeningReason.invalidMessage}
                        showErrorMessageWhenEmpty={false}
                    /> */}
                    <RadioButtonInput
                        name={inputs.reopeningReason.inputName}
                        label={lexicon.reopeningReason}
                        options={reopenReasonOptions}
                        selectedOption={inputs.reopeningReason.value}
                        onChange={handleOnChangeInputValue}
                        // className (optional): the css class to be applied in the main component tag
                    />
                </div>
            </CSSTransition>
        </SectionLayout>
    );
}

export default Problem;