import React, { useEffect, useState } from "react";
import style from "./Navbar.module.css";
import MenuButton from "./MenuButton/MenuButton";
import Link from "./Link/Link";
import SubMenu from "./SubMenu/SubMenu";

function Navbar (props) {
    const [isExpanded, setIsExpanded] = useState(
        (props.initialState === "expanded")? true : false
    );

    useEffect(() => {
        const autoCollapse = () => {
            if(window.innerWidth <= 1000) {
                setIsExpanded(false);
            }
        }

        window.addEventListener("resize", autoCollapse);

        return () => window.removeEventListener("resize", autoCollapse)
    }, []);

    const handleToggleMenu = () => {
        setIsExpanded(curSt => !curSt);
    }

    const items = props.items.map((item, idx) => {
        const useOnClickItem = item.useOnClickItem === undefined? true : item.useOnClickItem;
        const commonAttributes = {
            key: `menu-item-${item.id || idx}`,
            showLabel: isExpanded,
            className: item.className,
            icon: item.icon,
            label: item.label,
            onClick: useOnClickItem? props.onClickItem : null,
            disableTooltip: isExpanded 
        };

        if(item.type === "link") {
            return (
                <Link
                    {...commonAttributes}
                    path={item.path} 
                />
            );
        }

        if(item.type === "button") {
            if(useOnClickItem) {
                commonAttributes.onClick = () => {
                    item.onClick();
                    props.onClickItem();
                }
            } else {
                commonAttributes.onClick = item.onClick;
            }

            return (
                <MenuButton
                    {...commonAttributes}  
                    active={item.active}
                    selected={item.selected}
                />
            );
        }

        if(item.type === "subMenu") {
            return (
                <SubMenu  
                    {...commonAttributes}
                    maxWidth={item.maxWidth} 
                >
                    {item.content}
                </SubMenu>
            );
        }

        return null;
    });

    return (
        <div 
            className={`${style.Navbar} ${props.className || ""} ${isExpanded? style.expanded : ""}`}
            style={isExpanded? {width: props.expandedWidth} : {}}
        >
            <nav className={style.linksContainer}>
                {props.enableToggle && 
                    <MenuButton 
                        icon="menu" 
                        onClick={handleToggleMenu} 
                        tooltip={isExpanded? "Hide Menu" : "Show Menu"} 
                    />
                }
                {items}
            </nav>
        </div>
    );
}

export default Navbar;