import React, { useState, useEffect, useRef } from "react";
import MenuButton from "../MenuButton/MenuButton";
import style from "./SubMenu.module.css";

function SubMenu(props) {
    const [show, setShow] = useState(false);
    const [mouseOverWindow, setMouseOverWindow] = useState(false);
    const button = useRef();

    useEffect(() => {
        if(show && props.onShow) {
            props.onShow();
        } else if(props.onHide){
            props.onHide();
        }
    }, [show]);

    const handleOnClick = () => {
        setShow(curSt => !curSt);
        props.onClick && props.onClick();
    }

    const handleOnBlur = () => {
        if(mouseOverWindow) {
            button.current.focus();
        } else {
            setShow(false);

            if(props.onBlur) {
                props.onBlur();
            }
        }
    }

    return (
        <div className={`${style.SubMenu} ${show? style.show : ""} ${props.className || ""}`} >
            <MenuButton 
                ref={button} 
                icon={props.icon} 
                label={props.label}
                showLabel={props.showLabel} 
                active={show} 
                onClick={handleOnClick} 
                onBlur={handleOnBlur} 
                disableTooltip={props.disableTooltip || show || false}
            />
            <div 
                className={`${style.window}`} 
                style={{maxWidth: show? props.maxWidth : "0px"}}
                onMouseEnter={() => setMouseOverWindow(true)}
                onMouseLeave={() => setMouseOverWindow(false)}
            >
                <div className={style.content}>
                    {props.children}
                </div>
            </div>
        </div>
    )
}

export default SubMenu;