import React, { useState, useContext, useEffect, useRef } from "react";
import AppContext from "../../../context/appContext/AppContext";
import IconButton from "../../buttons/iconButton/IconButton";
import blueButtonStyle from "../../../generalStyles/blueButton.module.css";
import { CSSTransition, TransitionGroup } from "react-transition-group";
import style from "./Section.module.css";

function Section(props) {
    const [leftButton, setLeftButton] = useState(null);
    const [rightButton, setRightButton] = useState(null);
    const transitionDirection = useRef(null);
    const prevSection = useRef(null);
    const sectionButtons = useRef({});
    const appCtx = useContext(AppContext);

    // useEffect(() => {
    //     setLeftButton(sectionButtons.current.left);
    //     setRightButton(sectionButtons.current.right);
    // }, [props.currentSection]);

    const {currentSection, section, lastSection, endForm} = props;

    const insertButton = (position, button) => {
        if(position === "left") {
            setLeftButton(button);
        } else {
            setRightButton(button);
        }
    }

    if(currentSection !== prevSection.current) { //this check avoid a wrong transition direction due the component rerender done by useEffect
        transitionDirection.current = !prevSection.current && prevSection.current !== 0
        ? null
        : (currentSection - prevSection.current) > 0
        ? "Left" 
        : "Right";

        prevSection.current = currentSection;
    }
    
    return (
        <div className={style.sectionContainer}>
            <div className={`${style.Section} ${transitionDirection.current? style[`go${transitionDirection.current}`] : ""}`}>
                <TransitionGroup component={null} >
                    <CSSTransition
                        key={section.name}
                        timeout={200}
                        classNames={{
                            enter: style.enter,
                            enterActive: style.enterActive,
                            exit: style.exit,
                            exitActive: style.exitActive
                        }}
                    >
                        <section.component.type {...section.component.props}  insertButton={insertButton}/>
                    </CSSTransition>
                </TransitionGroup>
            </div>
            <div className={style.buttonsContainer}>
                {leftButton || 
                    <IconButton
                        className={`${style.leftButton} ${blueButtonStyle.blueButton} ${(currentSection === 0)? style.hide : ""}`}
                        icon={<span className={`${style.arrowIcon} material-icons`}>arrow_back_ios_new</span>}
                        iconPosition="left"
                        onClick={() => props.onChangeSection(currentSection - 1)}
                    >
                        {appCtx.lexicon.back}
                    </IconButton>
                }
                {
                    endForm
                    ? null
                    : <IconButton
                            className={`${style.rightButton} ${lastSection? style.finishButton : blueButtonStyle.blueButton}`}
                            icon={lastSection
                                ?   <span className="material-icons">done</span>
                                : <span className={`${style.arrowIcon} material-icons`}>arrow_forward_ios</span>
                            }
                            iconPosition="right"
                            onClick={() => props.onChangeSection(currentSection + 1)}
                            disabled={!section.isValid}
                        >
                            {appCtx.lexicon[lastSection? "finish" : "next"]}
                        </IconButton>
                }
            </div>
        </div>                      
    );
}

export default Section;