import React from "react";
import style from "./RadioButtonInput.module.css";

/*
    COMPONENT PROPS

    name (required): the input name
    label (required): the input label
    options (required): an array with the input options in the format: {value: "string"} or 
        {value: "string", label: "string"} or {value: "string", label: "string", description: "string"}
    selectedOption (optional): the current selected option (must match with the property 'value' of option object)
    onChange (required): the funtion to be executed when the input value changes
    error (required): a boolean to indicate if the input value is valid (the value validation must be done outside of the component)
    errorMessage (optional): the message to be shown if the input value is invalid
    className (optional): the css class to be applied in the main component tag
    style (optional): an style object to be applied in the main component tag
    labelOptionsContainerClassName (optional): the css class to be applied in the label tag
    optionsContainerClassName (optional): the css class to be applied in the options container
*/

function RadioButtonInput (props) {
    const handleOnChange = (event) => {
        props.onChange({
            name: event.target.name,
            value: event.target.value
        });
    }

    const options = [];
    let useGridLayout = false;

    for(let option of props.options) {
        const handleOnClickLabel = (event) => {
            event.target.previousSibling.click();
        }
        
        const el = (
            <div className={style.option} key={option.value}>
                <input 
                    name={props.name}
                    type="radio"
                    value={option.value}
                    checked={option.value === props.selectedOption}
                    onChange={handleOnChange}
                />
                <label onClick={handleOnClickLabel}>{option.label || option.value}</label>
            </div>
        );

        options.push(el);

        if(option.description) {
            options.push(
                <p className={`${style.description} ${props.optionClassName || ""}`} key={`desc-${option.value}`}>{option.description}</p>
            );
            useGridLayout = true;
        }
    }

    return (
        <div 
            className={`${style.RadioButtonInput} ${props.className || ""} ${props.error? style.error : ""}`}
            style={props.style || {}}
        >
            <div className={props.labelOptionsContainerClassName || ""}>
                <label className={`${style.label}`}>{props.label}</label>
                <div className={`${props.optionsContainerClassName || ""} ${useGridLayout? style.optionsContainerGridLayout : style.optionsContainerFlexLayout}`}>
                    {options}
                </div>
            </div>
            <p className={`${style.errorMessage}`}>{props.errorMessage}</p>
        </div>
    );
}

export default RadioButtonInput;