import React, { Fragment, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import style from "./Tooltip.module.css";

function Tooltip(props) {
    const [showTooltip, setShowTooltip] = useState(false);
    const [x, setX] = useState(0);
    const [y, setY] = useState(0);
    const sourceElement = useRef();
    const tooltipHideTimer = useRef(null);

    useEffect(() => {
        if(!sourceElementRef.current) return;

        const sourceElementInfo = sourceElementRef.current.getBoundingClientRect();
        const sourceElementXMiddle = sourceElementInfo.left + ((sourceElementInfo.right - sourceElementInfo.left) / 2);
        const sourceElementYMiddle = sourceElementInfo.top + ((sourceElementInfo.bottom - sourceElementInfo.top) / 2);

        switch(props.position) {
            case "top":
                setX(sourceElementXMiddle);
                setY(sourceElementInfo.top);
                break;
            case "left":
                setX(sourceElementInfo.left);
                setY(sourceElementYMiddle);
                break;
            case "right":
                setX(sourceElementInfo.right);
                setY(sourceElementYMiddle);
                break;
            default:
                setX(sourceElementXMiddle);
                setY(sourceElementInfo.bottom);
        }
    }, [props.position, showTooltip, sourceElement]);

    useEffect(() => {
        if(props.disabled) {
            setShowTooltip(false);
        }
    }, [props.disabled]);

    
    const childrenComponent = props.children;
    const sourceElementRef = childrenComponent.ref || sourceElement;

    const handleOnClick = () => {
        if(props.hideOnClick) {
            setShowTooltip(false);
        }

        if(childrenComponent.props.onClick) {
            childrenComponent.props.onClick();
        }
    }

    const handleOnMouseEnterSource = () => {
        clearTimeout(tooltipHideTimer.current);
        setShowTooltip(true);
    }

    const handleOnMouseEnterTooltip = () => {
        clearTimeout(tooltipHideTimer.current);
    }

    const hideTooltip = () => {
        tooltipHideTimer.current = setTimeout(
            () => setShowTooltip(false)
        , props.hideDelay ?? 200);
    }
    
    if(props.disabled) return childrenComponent;

    return (
        <Fragment>
            <childrenComponent.type 
                {...childrenComponent.props}
                ref={sourceElementRef}
                onMouseEnter={handleOnMouseEnterSource}
                onMouseLeave={hideTooltip}
                onClick={handleOnClick}
            />
            {showTooltip &&
                createPortal((
                    <div 
                        className={`${style.Tooltip} ${style[props.position || "bottom"]} ${props.className || ""} `}
                        style={{
                            left: `${x}px`,
                            top: `${y}px`
                        }}
                        onMouseEnter={handleOnMouseEnterTooltip}
                        onMouseLeave={hideTooltip}
                    >
                        <div 
                            className={`${style.content} ${props.contentClassName || ""}`}
                            style={props.contentStyle || {}}
                        >
                            {props.content}
                        </div>
                    </div>
                ), document.body)
            }
        </Fragment>
    );
}

export default Tooltip;