import React, { useContext, useEffect, useState } from "react";
import style from "./AppNavbar.module.css";
import LanguageSelector from "../languageSelector/LanguageSelector";
import AppContext from "../../context/appContext/AppContext";
import Navbar from "../navbar/Navbar";

function AppNavbar (props) {
    const [showLanguageSelector, setShowLanguageSelector] = useState(false);
    const appCtx = useContext(AppContext);
    const lexicon = appCtx.lexicon.theme.navbar;

    useEffect(() => {
        const handleLanguageSelector = () => {
            setShowLanguageSelector(window.innerWidth <= 1000);
        }

        handleLanguageSelector();

        window.addEventListener("resize", handleLanguageSelector);

        return () => window.removeEventListener("resize", handleLanguageSelector);
    }, []);

    const handleToggleAbout = () => {
        props.setShowAbout(curSt => !curSt);
    }

    const hideAbout = () => {
        props.setShowAbout(false);
    }

    const items = [
        // {
        //     type: "link",
        //     path: "/",
        //     icon: "home",
        //     label: lexicon.home
        // },
        {
            type: "button",
            onClick: () => {},
            icon: "description",
            active: true,
            selected: true,
            label: lexicon.categorization
        },
        // {
        //     type: "link",
        //     path: "/non-response-email",
        //     icon: "email",
        //     label: lexicon.nonResponseEmail
        // },
        // {
        //     type: "link",
        //     path: "/supported-applications",
        //     icon: "support_agent",
        //     label: lexicon.supportedApplications
        // },
        // {
        //     type: "link",
        //     path: "/sla-info",
        //     icon: "timer",
        //     label: lexicon.slaInfo
        // },
        // {
        //     type: null
        // },
        // {
        //     type: "link",
        //     path: "/settings",
        //     icon: "settings",
        //     label: lexicon.settings
        // },
        {
            type: "button",
            onClick: handleToggleAbout,
            icon: "info",
            label: lexicon.about,
            active: props.showAbout,
            useOnClickItem: false
        }
    ]

    if(showLanguageSelector) {
        items[4] = {
            type: "subMenu",
            maxWidth: "200px",
            content: <LanguageSelector />,
            icon: "language",
            label: lexicon.language,
            useOnClickItem: false
        };
    }

    return (
        <Navbar
            className={style.AppNavbar}
            enableToggle
            initialState="collapsed"
            expandedWidth="280px"
            items={items}
            onClickItem={hideAbout}
        />
    );
}

export default AppNavbar;