import React, { useState, useEffect, useContext, Fragment } from "react";
import AppContext from "../../context/appContext/AppContext";
import LanguageSelector from "../languageSelector/LanguageSelector";
import style from "./Header.module.css";

function Header (props) {
    const [showLanguageSelector, setShowLanguageSelector] = useState(false);
    const appCtx = useContext(AppContext);

    useEffect(() => {
        const handleLanguageSelector = () => {
            setShowLanguageSelector(window.innerWidth > 1000);
        }

        handleLanguageSelector();

        window.addEventListener("resize", handleLanguageSelector);

        return () => window.removeEventListener("resize", handleLanguageSelector);
    }, []);

    return (
        <header className={style.Header}>
            <div className={style.title}>
                <h1 className={style.logo}>CTI Tool</h1>
                <p className={style.separator}>-</p>
                <p>{appCtx.pageTitle}</p>  
            </div>
            {showLanguageSelector && 
                <Fragment>
                    <span className={`${style.icon} material-icons`}>language</span>
                    <LanguageSelector className={style.languageSelector}/>
                </Fragment>
            }
        </header>
    );
}

export default Header;