import React, { Fragment, useContext } from "react";
import inputStyle from "../Inputs.module.css";
import SectionLayout from "../../../sectionLayout/SectionLayout";
import BinaryQuestion from "../../../../inputs/binaryQuestion/BinaryQuestion";
import RadioButtonInput from "../../../../inputs/radioButtonInput/RadioButtonInput";
import breachReasonOptions from "../../../../../data/breachReasonOptions";
import AppContext from "../../../../context/appContext/AppContext";
import { CSSTransition } from "react-transition-group";

function BreachReason(props) {
    const appCtx = useContext(AppContext);
    const lexicon = appCtx.lexicon.theme.categorization.breachReason;
    const {inputs} = props;

    const handleOnChangeInputValue = (input) => {
        inputs[input.name].setValue(input.value);
    }

    return (
        <SectionLayout
            title={"Breach Reason"}
            description={lexicon.description}
        >
            <BinaryQuestion
                className={inputStyle.inputMargin}
                name={inputs.slaLost.inputName}
                label={lexicon.slaLost}
                labelPosition="left"
                yesLabel={appCtx.lexicon.yes}
                noLabel={appCtx.lexicon.no}
                value={inputs.slaLost.value}
                onChange={handleOnChangeInputValue}
                language={props.currentLanguage}
            />
            <CSSTransition
                in={inputs.slaLost.value === "yes"}
                timeout={200}
                unmountOnExit
                classNames={{
                    enter: inputStyle.fadeEnter,
                    enterActive: inputStyle.fadeEnterActive,
                    exit: inputStyle.fadeExit,
                    exitActive: inputStyle.fadeExitActive,
                }}
            >
                <div>
                    <BinaryQuestion
                        className={inputStyle.inputMargin}
                        style={{marginBottom: "0px"}}
                        name={inputs.breachWasWiproFault.inputName}
                        label={lexicon.breachWasWiproFault}
                        labelPosition="left"
                        yesLabel={appCtx.lexicon.yes}
                        noLabel={appCtx.lexicon.no}
                        value={inputs.breachWasWiproFault.value}
                        onChange={handleOnChangeInputValue}
                        language={props.currentLanguage}
                    />
                    <RadioButtonInput 
                        className={inputStyle.inputMargin}
                        style={{marginTop: "20px"}}
                        name={inputs.breachReason.inputName}
                        label={lexicon.breachReason}
                        options={breachReasonOptions[appCtx.currentLanguage]}
                        selectedOption={inputs.breachReason.value}
                        onChange={handleOnChangeInputValue}
                    />
                </div>
            </CSSTransition>
            {/* {(inputs.slaLost.value === "yes") && 
                <Fragment>
                    <BinaryQuestion
                        className={inputStyle.inputMargin}
                        name={inputs.breachWasWiproFault.inputName}
                        label={lexicon.breachWasWiproFault}
                        labelPosition="left"
                        yesLabel={appCtx.lexicon.yes}
                        noLabel={appCtx.lexicon.no}
                        value={inputs.breachWasWiproFault.value}
                        onChange={handleOnChangeInputValue}
                        language={props.currentLanguage}
                    />
                    <RadioButtonInput 
                        className={inputStyle.inputMargin}
                        name={inputs.breachReason.inputName}
                        label={lexicon.breachReason}
                        options={breachReasonOptions[appCtx.currentLanguage]}
                        selectedOption={inputs.breachReason.value}
                        onChange={handleOnChangeInputValue}
                    />
                </Fragment>
            } */}
        </SectionLayout>
    );
}

export default BreachReason;