import React, { createContext, useEffect, useState } from "react";
import appLexicon from "../../../data/lexicon/appLexicon";
import useBrowserStorage from "../../hooks/useBrowserStorage";

const value = {
    languages: ["en", "pt", "es"],
    currentLanguage: null,
    setCurrentLanguage: () => {},
    lexicon: null,
    appLexicon: null,
    pageTitle: null,
    setPageTitle: () => {},
    tempStorage: {
        set: () => {},
        get: () => {}
    },
};

const AppContext = createContext(value);

export function AppContextProvider(props) {
    const [pageTitle, setPageTitle] = useState("");
    const [tempStorage, setTempStorage] = useState({});
    const [currentLanguage, setCurrentLanguage] = useBrowserStorage({
        key: "language",
        initialValue: "en"
    });

    useEffect(() => {
        document.title = `CTI Tool - ${pageTitle}`;
    }, [pageTitle]);

    const saveInTempStorage = (key, value) => {
        setTempStorage(curSt => ({...curSt, [key]: value}));
    }

    const getFromTempStorage = (key) => {
        return tempStorage[key];
    }

    return (
        <AppContext.Provider value={{
            ...value,
            currentLanguage,
            setCurrentLanguage,
            lexicon: appLexicon[currentLanguage],
            appLexicon,
            pageTitle,
            setPageTitle,
            tempStorage: {
                set: saveInTempStorage,
                get: getFromTempStorage
            }
        }}>
            {props.children}
        </AppContext.Provider>
    );
}

export default AppContext;