import {useState, useEffect, useRef} from "react";

function useBrowserStorage({key, initialValue, useStoredValue = true, storageType = "local"}) {
    const storage = useRef((storageType === "local")? localStorage : sessionStorage);
    const [state, setState] = useState((useStoredValue && JSON.parse(storage.current.getItem(key))) || initialValue);

    useEffect(() => {
        storage.current.setItem(key, JSON.stringify(state));
    }, [state, key]);

    return [state, setState];
}

export default useBrowserStorage;