import React, { forwardRef, useImperativeHandle, useRef } from "react";
import style from "./MenuButton.module.css";
import Tooltip from "../../tooltip/Tooltip";

function MenuButton(props, ref) {
    const button = useRef();

    useImperativeHandle(ref, () => ({
        focus: () => button.current.focus(),
        blur: () => button.current.blur()
    }));

    return (
        <Tooltip
            position="right"
            content={props.tooltip || props.label}
            hideDelay={0}
            disabled={props.disableTooltip}
            hideOnClick
        >
            <button 
                ref={button}
                className={`${style.MenuButton} ${props.active? style.active : ""} ${props.selected? style.selected : ""} ${props.className || ""}`} 
                onClick={props.onClick || null} 
                onBlur={props.onBlur || null}
                onFocus={props.onFocus || null}
            >
                <span  className={`${style.icon} ${style.filled}  material-icons`}>{props.icon}</span>
                <span className={`${style.icon} ${style.outlined} material-icons-outlined`}>{props.icon}</span>
                <p className={`${style.label} ${props.showLabel? "" : style.hideLabel }`}>{props.label}</p>
            </button>
        </Tooltip>
    );
}

export default forwardRef(MenuButton);