import React from "react";
import style from "./Card.module.css";

function Card (props) {

    return (
        <div 
            className={`${style.Card} ${props.hoverEffect? style.hoverEffect : ""} ${props.className || ""}`}
            style={props.style || {}}
        >
            {props.children}
        </div>
    );
}

export default Card;