import React, { useContext } from "react";
import AppContext from "../../../context/appContext/AppContext";
import IconButton from "../../buttons/iconButton/IconButton";
import blueButtonStyle from "../../../generalStyles/blueButton.module.css";
import style from "./ResetConfirmation.module.css";

function ResetConfirmation(props) {
    const appCtx = useContext(AppContext);

    return (
        <div className={style.ResetConfirmation}>
            <p>{appCtx.lexicon.theme.form.resetConfirmation}</p>
            <div className={style.buttonsContainer}>
            <IconButton
                className={blueButtonStyle.blueButton}
                icon={<span className={`material-icons`}>close</span>}
                iconPosition="right"
                onClick={props.onCancelFormReset}
            >
                {appCtx.lexicon.no}
            </IconButton>
            <IconButton
                className={blueButtonStyle.blueButton}
                icon={<span className={`material-icons`}>done</span>}
                iconPosition="right"
                onClick={props.onResetForm}
            >
                {appCtx.lexicon.yes}
            </IconButton>
            </div>
        </div>
    );
}

export default ResetConfirmation;