import React, { useContext } from "react";
import style from "./IncidentInfo.module.css";
import inputStyle from "../Inputs.module.css";
import SectionLayout from "../../../sectionLayout/SectionLayout";
import InputField from "../../../../inputs/inputField/InputField";
import countries from "../../../../../data/countries";
import AppContext from "../../../../context/appContext/AppContext";

function IncidentInfo(props) {
    const appCtx = useContext(AppContext);
    const lexicon = appCtx.lexicon.theme.categorization.incidentInfo;
    const {inputs} = props;

    const handleOnChangeInputValue = (input) => {
        inputs[input.name].setValue(input.value);
    }

    // const priorities = [
    //     {label: appCtx.lexicon.critical, value: "critical"},
    //     {label: appCtx.lexicon.high, value: "high"},
    //     {label: appCtx.lexicon.medium, value: "medium"},
    //     {label: appCtx.lexicon.low, value: "low"},
    //     {label: appCtx.lexicon.extended, value: "extended"}
    // ];

    const countryOptions = countries[appCtx.currentLanguage].map(country => ({
        value: country, 
        label: `${country.slice(0, 1).toUpperCase()}${country.slice(1)}`
    }));

    return (
        <SectionLayout
            className={style.sectionLayout}
            title={lexicon.title}
            description={lexicon.description}
        >
            {/* <InputField 
                className={inputStyle.inputField}
                labelClassName={style.selectLabel}
                type="text"
                name={inputs.incident.inputName}
                label={lexicon.incident}
                labelPosition="left"
                uppercase
                placeholder={lexicon.incidentPlaceholder}
                onChange={handleOnChangeInputValue}
                debouncing
                value={inputs.incident.value}
                error={!inputs.incident.isValid}
                errorMessage={inputs.incident.invalidMessage && inputs.incident.invalidMessage[appCtx.currentLanguage]}
                showErrorMessageWhenEmpty={false}
            /> */}
            {/* <InputField 
                className={inputStyle.inputField}
                labelClassName={style.selectLabel}
                type="select"
                name={inputs.priority.inputName}
                label={appCtx.lexicon.priority}
                labelPosition="left"
                placeholder={lexicon.priorityPlaceholder}
                options={priorities}
                onChange={handleOnChangeInputValue}
                value={inputs.priority.value}
                error={!inputs.priority.isValid}
                errorMessage={inputs.priority.invalidMessage}
                showErrorMessageWhenEmpty={false}
            /> */}
            <InputField 
                className={inputStyle.inputField}
                labelClassName={style.selectLabel}
                type="select"
                name={inputs.country.inputName}
                label={appCtx.lexicon.country}
                labelPosition="left"
                placeholder={lexicon.countryPlaceholder}
                options={countryOptions}
                onChange={handleOnChangeInputValue}
                value={inputs.country.value}
                error={!inputs.country.isValid}
                errorMessage={inputs.country.invalidMessage}
                showErrorMessageWhenEmpty={false}
            />
            <InputField 
                className={inputStyle.inputField}
                labelClassName={style.selectLabel}
                type="text"
                name={inputs.pbi.inputName}
                label="PBI"
                labelPosition="left"
                optionalText={`(${appCtx.lexicon.optional})`}
                uppercase
                placeholder={lexicon.pbiPlaceholder}
                onChange={handleOnChangeInputValue}
                // debouncing
                value={inputs.pbi.value}
                error={!inputs.pbi.isValid}
                errorMessage={inputs.pbi.invalidMessage && inputs.pbi.invalidMessage[appCtx.currentLanguage]}
                showErrorMessageWhenEmpty={false}
            />
            <InputField 
                className={inputStyle.inputField}
                labelClassName={style.selectLabel}
                type="text"
                name={inputs.kba.inputName}
                label="KBA"
                labelPosition="left"
                optionalText={`(${appCtx.lexicon.optional})`}
                uppercase
                placeholder={lexicon.kbaPlaceholder}
                onChange={handleOnChangeInputValue}
                // debouncing
                value={inputs.kba.value}
                error={!inputs.kba.isValid}
                errorMessage={inputs.kba.invalidMessage && inputs.kba.invalidMessage[appCtx.currentLanguage]}
                showErrorMessageWhenEmpty={false}
            />
        </SectionLayout>
    );
}

export default IncidentInfo;