import React, { Fragment, useContext, useEffect, useRef } from "react";
import AppContext from "../../../context/appContext/AppContext";
import SectionLayout from "../../sectionLayout/SectionLayout";
import style from "./Resolution.module.css";

function Resolution(props) {
    const appCtx = useContext(AppContext);
    const resolutionText = useRef();
    const copyButton = useRef();
    const copyButtonTimeoutId = useRef();

    const handleOnCopy = () => {
        navigator.clipboard.writeText(clipboardText.join("\n"));

        clearTimeout(copyButtonTimeoutId.current);
        copyButtonTimeoutId.current = setTimeout(() => copyButton.current.blur(), 2000);
    }
        
    const lexicon = appCtx.lexicon.theme.categorization.resolution;

    const formFields = {...props.formFields};

    // formFields.incident = formFields.incident.toUpperCase();

    if(formFields.pbi) {
        formFields.pbi = formFields.pbi.toUpperCase();
    }

    if(formFields.kba) {
        formFields.kba = formFields.kba.toUpperCase();
    }

    // formFields.priority = appCtx.lexicon[formFields.priority];

    const htmlText = {};
    const clipboardText = [];

    for(let key in formFields) {
        const value = formFields[key];
 
        if(value) {
            htmlText[key] = (
                <div className={style.row}>
                    <p className={style.label}>
                        {`${lexicon[key].toUpperCase()}: `}
                    </p>
                    <p className={style.value}>
                        {(value === "yes" || value === "no")
                            ? appCtx.lexicon[value] 
                            : value
                        }
                    </p>
                </div>
            );

            if(key === "sqlCode") continue;
            clipboardText.push(`${appCtx.appLexicon.en.theme.categorization.resolution[key].toUpperCase()}: ${value} |`);
        }
    }

    const timestamp = `${new Date().toLocaleString()}`;
    htmlText.date = <p className={style.date}>{lexicon.generatedDate} {timestamp}</p>
    clipboardText.push(`\n${appCtx.appLexicon.en.theme.categorization.resolution.generatedDate}: ${timestamp} |`)

    return (
        <SectionLayout
            inputsContainerClassName={style.inputsContainer}
            title={lexicon.title}
            description={lexicon.description}
        >
            <div className={style.Resolution}>
                <div ref={resolutionText}>
                    {htmlText.incident}
                    {htmlText.priority}
                    {htmlText.country}
                    {htmlText.pbi}
                    {htmlText.kba}
                    {htmlText.classification}
                    {htmlText.incClassification}
                    {htmlText.tier1}
                    {htmlText.tier2}
                    {htmlText.tier3}
                    {htmlText.tier4}
                    {htmlText.tier5}
                    {htmlText.problem}
                    {htmlText.diagnosisMatchProblem}
                    {htmlText.isReopening}
                    {(props.formFields.isReopening === "yes") && htmlText.reopeningReason}
                    {htmlText.solution}
                    {htmlText.usedSql}
                    {(props.formFields.usedSql === "yes") && htmlText.sqlCode}
                    {htmlText.userGuided && htmlText.userGuided}
                    {htmlText.slaLost}
                    {(props.formFields.slaLost === "yes") &&
                        <Fragment>
                            {htmlText.breachWasWiproFault}
                            {htmlText.breachReason}
                        </Fragment>
                    }
                </div>
                <div className={style.dateCopy}>
                    {htmlText.date}
                    <button ref={copyButton} className={style.button} onClick={handleOnCopy}>
                        <span className={style.copy}>
                            <span>{appCtx.lexicon.copy}</span>
                            <span className={`${style.icon} material-icons-round`}>content_copy</span>
                        </span>
                        <span className={style.copied}>
                            <span>{appCtx.lexicon.copied}</span>
                            <span className={`${style.icon} material-icons-round`}>done</span>
                        </span>
                    </button>
                </div>
            </div>
        </SectionLayout>
        
    );
}

export default Resolution;