import React from "react";
import style from "./IconButton.module.css";

function IconButton(props) {

    return (
        <button 
            className={`${style.IconButton} ${props.children? style[props.iconPosition] || style.left : ""} ${props.className || ""} ${props.active? props.activeClassName || style.active : ""}`} 
            style={props.style}
            onClick={() => props.onClick()} 
            disabled={props.disabled}
        >
            <div className={`${style.icon} ${props.active? style.active : ""}`}>
                {props.icon && 
                    <span className={props.activeIcon? style.defaultIcon : ""}>{props.icon}</span>
                }
                {props.activeIcon && 
                    <span className={style.activeIcon}>{props.activeIcon}</span>
                }
            </div>
            {props.children && 
                <span className={style.text}>{props.children}</span>
            }
        </button>
    );
}

export default IconButton;