import React, { useState, useContext, useEffect } from "react";
import AppContext from "../../../context/appContext/AppContext";
import IconButton from "../../buttons/iconButton/IconButton";
import FormTimeline from "../../formTimeline/FormTimeline";
import style from "./Timeline.module.css";
import blueButtonStyle from "../../../generalStyles/blueButton.module.css";
import SlidingPanel from "../../slidingPanel/SlidingPanel";

function Timeline(props) {
    const [shrinkTimeline, setTinyTimeline] = useState(false);
    const [shrinkTimelineSetByUser, setTinyTimelineSetByUser] = useState(false);
    const [smallWindowResize, setSmallWindowResize] = useState(false);
    const [bigWindowResize, setBigWindowResize] = useState(false);
    const appCtx = useContext(AppContext);

    useEffect(() => {
        function checkWindowSize() {
            if(window.innerWidth < 1000 && !smallWindowResize) {
                setSmallWindowResize(true);
                setBigWindowResize(false);
                setTinyTimeline(true);
            } else if(window.innerWidth > 1000 && !bigWindowResize) {
                setSmallWindowResize(false);
                setBigWindowResize(true);
                if(!shrinkTimelineSetByUser) {
                    setTinyTimeline(false);
                }
            }
        }

        checkWindowSize();

        window.addEventListener("resize", checkWindowSize);

        return () => window.removeEventListener("resize", checkWindowSize);
    },[smallWindowResize, bigWindowResize]);

    const toggleTimeline = () => {
        setTinyTimelineSetByUser(!shrinkTimeline);
        setTinyTimeline(curSt => !curSt);
    }

    const timelineSteps = props.sections.map(section => ({name: section.name, disabled: !section.isValid}));

    return (
        <SlidingPanel
            open={!shrinkTimeline}
            minWidth="68px"
            showButton={!smallWindowResize}
            onOpen={toggleTimeline}
            onClose={toggleTimeline}
        >
            <FormTimeline 
                className={style.formTimeline}
                steps={timelineSteps} 
                currentStep={props.currentSection} 
                onClickStep={props.onClickStep}
                tiny={shrinkTimeline}
            />
            <IconButton
                className={`${blueButtonStyle.blueButton} ${style.resetButton} ${shrinkTimeline? style.shrinkResetButton : ""}`}
                icon={<span className="material-icons">restart_alt</span>}
                iconPosition="right"
                onClick={props.onClickReset}
            >
                {shrinkTimeline? "" : appCtx.lexicon.reset}
            </IconButton>
        </SlidingPanel>
    );
}

export default Timeline;