import React, { useState } from "react";
import Card from "../card/Card";
import style from "./Form.module.css";
import { CSSTransition, SwitchTransition } from "react-transition-group";
import Section from "./Section/Section";
import ResetConfirmation from "./ResetForm/ResetConfirmation";
import Timeline from "./Timeline/Timeline";

function Form(props) {
    const [resetConfirmation, setResetConfirmation] = useState();

    const goToSection = (index) => {
        props.onChangeSection(index);
    }

    const handleOnResetForm = () => {
        setResetConfirmation(true);
    }

    const onResetForm = () => {
        props.sections.forEach(section => {
            if(section.inputs) {
                for(let key in section.inputs) {
                    section.inputs[key].reset();
                }
            }
        });

        setResetConfirmation(false);
        goToSection(0);
    }

    const currentSection = props.currentSection || 0;
    const section = props.sections[currentSection];

    const transitionClasses = {
        enter: style.resetConfirmationEnter,
        enterActive: style.resetConfirmationEnterActive,
        exit: style.resetConfirmationExit,
        exitActive: style.resetConfirmationExitActive,
    };

    return (
        <div className={`${style.Form} ${props.className || ""}`}>
            <div className={style.formContainer}>
                <Card className={style.formCard}>
                    <SwitchTransition>
                        <CSSTransition
                            key={resetConfirmation? "resetConfirmation" : "section"}
                            in={resetConfirmation}
                            timeout={200}
                            unmountOnExit
                            classNames={transitionClasses}
                        >
                            {resetConfirmation
                                ? <ResetConfirmation
                                    onResetForm={onResetForm}
                                    onCancelFormReset={() => setResetConfirmation(false)}
                                />
                                : <Section
                                    currentSection={currentSection}
                                    section={section}
                                    lastSection={currentSection === props.sections.length - 2}
                                    endForm={currentSection === props.sections.length - 1}
                                    onChangeSection={props.onChangeSection}
                                />
                            }
                        </CSSTransition>
                    </SwitchTransition>
                </Card>
            </div>
            <Timeline
                sections={props.sections}
                currentSection={currentSection}
                onClickStep={goToSection}
                onClickReset={handleOnResetForm}
            />
        </div>
    );
}

export default Form;